script.css:
@import url('https://fonts.googleapis.com/css2?family=Monda:wght@400;700&display=swap');
.website { font-family: 'Monda', sans-serif; }

@keyframes ring2 {
    0% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
        transform: rotate(0) scale(1) skew(1deg)
    }

    10% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
        transform: rotate(-25deg) scale(1) skew(1deg)
    }

    20% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
        transform: rotate(25deg) scale(1) skew(1deg)
    }

    30% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
        transform: rotate(-25deg) scale(1) skew(1deg)
    }

    40% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
        transform: rotate(25deg) scale(1) skew(1deg)
    }

    50% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
        transform: rotate(0) scale(1) skew(1deg)
    }

    100% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
        transform: rotate(0) scale(1) skew(1deg)
    }
}

.hotline-bar {
    position: fixed; bottom:27px; right:20px;
    background: #d8a72c;
    width: 180px; height:35px; line-height:35px;
    border-radius: 10px; z-index:-1; padding-left:10px; font-weight:bold; 
}
.hotline-bar a { font-size:16px; color:#FFF; }
.fix-icon-support { position: fixed; right: 10px; bottom: 20px; width: 50px; z-index:10; }
.fix-icon-support .icon-sp { display:block;}
.fix-icon-support .icon-sp + .icon-sp { margin-top:10px;}
.fix-icon-support .icon-sp img { width:50px; }
.fix-icon-support .icon-zalo img {
    -webkit-animation: ring2  1s infinite ease-in-out;
    animation: ring2 1s infinite ease-in-out;
    -webkit-transform-origin: 50% 50%;
    -ms-transform-origin: 50% 50%;
    transform-origin: 50% 50%
}
.fix-icon-support .icon-sp.icon-phone img {
    background-color: #d8a72c;
    border: 1px solid #d8a72c;
    border-radius: 50%;
}
.item-view-landing-page .item-img-icon { margin: 0 -10px;}
.item-view-landing-page .item-img-icon .item { padding:0 10px;}
.logo img { width:126px; }
.has-fixed .logo img { width:108px; margin:5px; }
.space-header {
    height: 1px;
}
.form-control.has-calendar-icon {
    padding-left: 40px;
}
#main-menu .mobile-menu>ul>li>a {
    color: #dfb339;
}
#header .icon-menu { color:#000; }
#header { background-color: #FFF; }

.has-fixed #header {
    position: fixed;
    top: 0;
    width: 100%;
    background-color: #FFF;
}
.bg-full-width {
  width: 100vw;
  position: relative;
  left: 50%;
  right: 50%;
  margin-left: -50vw;
  margin-right: -50vw;
  overflow: hidden;
}
.bg-1 { background-color:#f9f9e7;}
.bg-2 { background-color:#60504b;}
.bg-2 .btn-more { color:#e3d0bc; border:1px solid; border-radius:5px; padding:5px 10px; display:inline-block;}
.bg-2 .btn-more:hover { color:#FFF;}
.bg-2 .title { color:#e3d0bc; }
.bg-3 { background-color:#efebe4;}
.title1 { text-align:center; margin: 30px 0; color: #d8a72c;}
.title1 img { width:320px; }
.title { text-align:left; padding: 10px 0; }
.title-name { font-size:44px; font-weight:normal; position:relative; padding-bottom:10px;}
.title-name:after { content: " "; display:block; width:142px; height:1px; position:absolute; bottom:0; left:0; border-bottom:1px solid; }
.title>* { background-color:unset; padding:unset; color:#d8a72c;}
.item-view-landing-page-slide .slick-list { margin-left:-10px;}
.info h1 { color:#d8a72c;}
.btn-sendinquery { background-color:#f5b158; color:#FFF; }
.btn-sendinquery:before, .btn-call:before { padding-right:5px;}
.fa-long-arrow-right:before {
    content: "\f178";
}
.ffa:before {
    font-family: FontAwesome;
}
.f-contact { position:relative; padding: 30px 0; margin: 30px 0 50px;}
.f-contact:after { content:" "; height:1px; position:absolute; bottom:0px; left:50%; width:300px; margin-left:-150px; background-color: #60504b; }
.f-contact a { font-weight:bold; }
.f-content { padding: 20px; }
.newsletter-form { margin:20px 0; position:relative; width:320px;}
.btn-newsletter { position:absolute; right:0; top:0; width:90px; height:100%; background-color:#d8a72c; border:none; color:#FFF; border-radius: 0 5px 5px 0;}
.blog-slide-content { background-color:#FFF; }
.blog-slide-content-info { height:188px; padding: 10px; }
a.blog-item-title { height: 45px; }
.blog-slide-content-info > p { height: 94px; overflow:hidden; }
.social-icons { padding: 10px 0;}
.social-icons a { display:inline-block; border-radius:50%; height:40px; width:40px; line-height:40px; border: 1px solid; color:#000; text-align:center; margin: 5px;}
.fa-youtube-play:before {
    content: "\f16a";
}
.form-booking-info {
    padding: 20px;
}
.item-view-slide-image-product .img figure,
.item-detail-infomation .list-image-detail .img figure {
    padding-top: 0px;
}
.item-view-slide-image-product .img figure a,
.item-detail-infomation  .list-image-detail .img figure a {
    position: relative;
    display: block;
}

.change-language ol li { float:left; list-style:none; margin-left:5px;}
#main-menu .mobile-menu > ul .change-language ol li a { height:unset; }
.change-language ol { padding:0; margin:0; }
.change-language ol:after { display:block; clear:both; content: "" ;}
.p-sale { font-weight:bold; }
#footer { font-size:14px; background-color:#f5f1ee; }
@media (min-width: 768px)  {
    #main-menu .desktop-menu>ul>li>a {color:#000;  text-transform:uppercase;  }
    #main-menu .desktop-menu>ul>li>a:hover, #main-menu .desktop-menu>ul>li.active>a { color:#d8a72c; }
    #main-menu .desktop-menu>ul>li:hover ul.sub-menu a { background-color: #d8a72c;}
    .home-page #header { position: absolute;  left: 0; width: 100%;  background-color: unset; }
    .has-fixed.home-page #header { position: fixed; background-color: #FFF; }
    .title { font-size:40px; }
    .f-content { padding: 40px; }
    .language-style { width:120px; position:relative; height:22px; }
    .change-language ol { width:100%; position:absolute; top:0px; left:0;}
.form-booking-info {
    padding: 40px;
}
#main-menu { margin-top:40px; }
.has-fixed #main-menu { margin-top:30px;}
#main-menu .desktop-menu > ul {   display: -moz-flex; display: -ms-flex; display: flex;  align-items: flex-start;   justify-content: flex-start; flex-wrap: wrap; text-align:center; }
#main-menu .desktop-menu > ul > li { list-style:none; flex-grow: 1; }
#main-menu .root-c > a { margin:0 5px;
    color: white; padding: 4px 0px; 
    height: inherit;
    vertical-align: middle;
    display: table-cell;
    display: inline-block;
    border-bottom: 1px solid transparent;
    border-top: 1px solid transparent; 
}
.desktop-menu>ul>li>a:before { display:none; } 
#main-menu .root-c > a {
    margin: 0 10px;
    padding: 8px 0px;
    font-size: 14px;
    text-transform: uppercase;
}

.product-detail-layout { padding-right: 34%;  position: relative; }
    .product-sidebar {  margin-left: 10px;  position: absolute; right: 0px; width: 33%;  background-color: #FFF; }
    .product-detail-layout .sidebar-fixed {  position: fixed;  z-index: 10; top: 75px;  left: 66%;  width: 32%; }

}
@media only screen and (min-width: 1080px) {
    .item-odd-even .item-od-content { width:860px; margin:0 auto;}
    .item-odd-even:nth-child(odd) { background-color:#ffe8d4; }
    .item-odd-even:nth-child(even) .col-left  { float:right;}
    .form-booking-info { padding: 40px;}
    .form-booking-info-home { width:480px;}
}
@media only screen and (min-width: 1280px) {
    .product-detail-layout .sidebar-fixed { width: 370px; left:64%; }
}
